import { translate } from '../shared/i18n';
import { useI18n, LanguageSwitcher, type Locale } from './i18n';
import { useCallback, useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react';
import type { Session, SupabaseClient } from '@supabase/supabase-js';
import { Activity, ArrowDownToLine, ArrowRight, ArrowUpRight, BarChart3, CalendarDays, Check, CheckCheck, ChevronLeft, ChevronRight, Clock3, Copy, FolderKanban, LayoutDashboard, ListTodo, LogOut, MoreHorizontal, Pencil, Play, Plus, RefreshCw, Settings2, ShieldCheck, Square, Trash2, Users, X } from 'lucide-react';
import { createService } from '../shared/service';
import { createDemoService, type DemoService } from '../shared/demo-service';
import type { DemoWorkspace } from '../shared/demo-data';
import { FinanceArea } from './finance';
